<script setup lang="ts">
import {computed,ref} from 'vue';import {Plus,Trash2} from 'lucide-vue-next';
import {rowLayout} from './layout';import {insertLayoutItem,cabinetOrderError} from './dragGeometry';
import FloorPlan from './FloorPlan.vue';import {request,infraNames,moduleProducts} from './model';import type {State,ModuleTemplate} from './model';import {previewPlan} from './templatePlan';
const props=defineProps<{state:State;initial:ModuleTemplate}>();const emit=defineEmits<{saved:[state:State];busy:[busy:boolean]}>();
const form=ref<ModuleTemplate>(JSON.parse(JSON.stringify(props.initial)));const error=ref(''),busy=ref(false);const preview=computed(()=>previewPlan(form.value.plan));const selected=ref('');
function resize(){const p=form.value.plan;const left=preview.value.module.rackLeft,right=preview.value.module.rackRight;p.rack_names={L:Array.from({length:left},(_,i)=>p.rack_names?.L?.[i]||'L'+String(i+1).padStart(2,'0')),R:Array.from({length:right},(_,i)=>p.rack_names?.R?.[i]||'R'+String(i+1).padStart(2,'0'))}}
function materialize(){if(!form.value.plan.layout){form.value.plan.layout=preview.value.infra.map(i=>({name:i.name,kind:i.kind,side:i.side,after_rack:i.afterRack,placement:i.placement,...(i.order?{order:i.order}:{})}));delete form.value.plan.infra}}
function insertRack(id:string,side:string,beforeId:string){
 const old=preview.value,rows=['L',...(old.module.type==='double'?['R']:[])].map(side=>({side,tiles:rowLayout(old.module,old.racks,old.infra,side)}));
 const next=insertLayoutItem(rows,id,side,beforeId||null);if(!next)return;
 const rackIDs=new Set(old.racks.map(r=>r.id)),rackRows={L:next.L.filter(id=>rackIDs.has(id)),R:next.R.filter(id=>rackIDs.has(id))};
 const invalid=cabinetOrderError(rackRows,old.module.type==='double');if(invalid){error.value=invalid;return}
 const positions=new Map<string,{side:string;after_rack:number;order:number}>();
 for(const side of ['L','R'] as const){let count=0,order=0;for(const id of next[side]){if(rackIDs.has(id))count++;else positions.set(id,{side,after_rack:count,order:order++})}}
 materialize();const p=form.value.plan;
 p.layout=p.layout!.map((slot,i)=>{if(slot.placement==='integrated'){const rack=old.racks.find(r=>r.side===slot.side&&r.index===slot.after_rack);if(rack){const target=rackRows.L.includes(rack.id)?'L':'R';return {...slot,side:target,after_rack:rackRows[target].indexOf(rack.id)+1}}}return {...slot,...positions.get(old.infra[i].id)}});
 p.rack_names={L:rackRows.L.map(id=>old.racks.find(r=>r.id===id)!.name),R:rackRows.R.map(id=>old.racks.find(r=>r.id===id)!.name)};
 p.rack_count=rackRows.L.length;p.rack_left=rackRows.L.length;p.rack_right=rackRows.R.length;
 const target=rackRows.L.includes(id)?'L':'R';selected.value=target+(rackRows[target].indexOf(id)+1);error.value='';
}

function moveFacility(id:string,side:string,after:number,beforeId:string){materialize();const old=preview.value;const index=old.infra.findIndex(i=>i.id===id);if(index<0)return;const slot=form.value.plan.layout![index];slot.side=side;slot.after_rack=after;const siblings=old.infra.map((i,index)=>({i,index})).filter(v=>v.i.id!==id&&v.i.side===side&&v.i.afterRack===after&&v.i.placement==='inline').sort((a,b)=>(a.i.order||0)-(b.i.order||0));const insert=beforeId?siblings.findIndex(v=>v.i.id===beforeId):siblings.length;if(insert<0)return;slot.order=insert;for(let i=0;i<siblings.length;i++)form.value.plan.layout![siblings[i].index].order=i>=insert?i+1:i}
async function save(){if(busy.value)return;busy.value=true;emit('busy',true);error.value='';try{emit('saved',await request<State>('/templates'+(form.value.id?'/'+form.value.id:''),form.value.id?'PUT':'POST',{revision:props.state.revision,template:form.value}))}catch(e){error.value=(e as Error).message}finally{busy.value=false;emit('busy',false)}}
resize();
</script>
<template><form class="template-editor" @submit.prevent="save"><div v-if="error" class="error-banner" role="alert">{{error}}</div><div class="form-grid"><label>模板名称<input v-model="form.name" required maxlength="80" placeholder="例如：标准双排8柜"/></label><label>微模块型号<input v-model="form.plan.product_model" list="template-products" maxlength="120"/><datalist id="template-products"><option v-for="m in moduleProducts" :key="m" :value="m"/></datalist></label><label>默认模块名称<input v-model="form.plan.name" required maxlength="80"/></label><label>排列方式<select v-model="form.plan.type" aria-label="模板排列方式" @change="resize"><option value="single">单排</option><option value="double">双排</option></select></label><label v-if="form.plan.type==='single'">机柜数量<input v-model.number="form.plan.rack_count" type="number" min="1" max="24" required @change="resize"/></label><template v-else><label>左列机柜数<input v-model.number="form.plan.rack_left" type="number" min="1" max="12" required @change="resize"/></label><label>右列机柜数<input v-model.number="form.plan.rack_right" type="number" min="1" max="12" required @change="resize"/></label></template></div><div class="form-section-heading"><h3>布局预览</h3><span class="muted small">拖动调整模板内的柜序</span></div><FloorPlan :module="preview.module" :racks="preview.racks" :infra="preview.infra" :devices="[]" :models="[]" :selected="selected" :zoom="100" :busy="busy" @select="selected=$event" @insert-rack="insertRack" @move-infrastructure="moveFacility"/>
 <details class="compact-help"><summary>柜名与基础设施</summary><div class="form-grid"><label v-for="side in form.plan.type==='double'?['L','R']:['L']" :key="side">{{side}}列柜名<div class="template-rack-names"><input v-for="(_,i) in form.plan.rack_names![side]" :key="i" v-model="form.plan.rack_names![side][i]" :aria-label="`模板${side}列第${i+1}柜名`" required maxlength="80"/></div></label></div><div class="form-section-heading"><h3>设施位置</h3><button type="button" class="secondary" @click="materialize();form.plan.layout!.push({name:'空调',kind:'ac',side:'L',after_rack:0,placement:'inline'})"><Plus :size="14"/>新增设施</button></div><div v-for="(slot,i) in (form.plan.layout||[])" :key="i" class="template-slot-row"><input v-model="slot.name" required maxlength="80" aria-label="模板设施名称"/><select v-model="slot.kind" aria-label="模板设施类型"><option v-for="(name,kind) in infraNames" :key="kind" :value="kind">{{name}}</option></select><select v-model="slot.side" aria-label="模板设施所属列"><option value="L">L列</option><option v-if="form.plan.type==='double'" value="R">R列</option></select><select v-model="slot.placement" aria-label="模板设施安装方式"><option value="inline">柜后/列首</option><option value="integrated">柜内</option></select><input v-model.number="slot.after_rack" type="number" :min="slot.placement==='integrated'?1:0" :max="slot.side==='L'?preview.module.rackLeft:preview.module.rackRight" aria-label="模板设施位置" required/><button type="button" class="icon-button" aria-label="删除模板设施" @click="form.plan.layout!.splice(i,1)"><Trash2 :size="15"/></button></div><button v-if="!form.plan.layout" type="button" class="text-button" @click="materialize">展开默认设施位置</button></details>
 <details class="compact-help"><summary>备注与填写帮助</summary><label>模板说明<textarea v-model="form.description" maxlength="1000" rows="2"/></label><p>0表示列首，1表示第1柜后；柜内设施从1开始。缩减柜数后请调整越界设施。修改模板只影响以后新建的模块，不修改已建机房。</p><p>模板只包含布局，不保存设备、IP、SN、网络成员和实际连接。</p></details><div class="modal-actions"><span class="muted small">42U · {{preview.racks.length}} 柜</span><button class="primary" :disabled="busy">保存模板</button></div></form></template>
